using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEngine.UI;using UnityEditor;using UnityEditor.SceneManagement;
namespace CampaignDemo.Editor {
 [InitializeOnLoad]public static class HotkeyPreviewVerification {
  const string Key="HotkeyPreviewVerification";static double started;static int phase;static readonly List<string> rows=new List<string>();static CampaignHUD hud;
  static string Root{get{var p=Path.GetFullPath(Path.Combine(Application.dataPath,"../VerificationOutputs"));Directory.CreateDirectory(p);return p;}}
  static HotkeyPreviewVerification(){if(SessionState.GetBool(Key,false)){started=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}}
  public static void Run(){EditorSceneManager.OpenScene("Assets/Scenes/DoubleValley9x.unity");SessionState.SetBool(Key,true);started=EditorApplication.timeSinceStartup;EditorApplication.update+=Poll;EditorApplication.isPlaying=true;}
  static void Check(bool ok,string name){if(!ok)throw new Exception(name);rows.Add("PASS "+name);Debug.Log("HOTKEY_PASS "+name);}
  static void Near(float a,float b,string name){Check(Mathf.Abs(a-b)<.001f,name+" "+a+" / "+b);}
  static void Test(BattleWorld w){w.enabled=false;w.GetComponent<BattleAIController>().enabled=false;w.GetComponent<AIBasicCommander>().enabled=false;w.GetComponent<InfantryProduction>().enabled=false;w.GetComponent<LocalTacticalBattle>().enabled=false;w.SetPlayer("A");w.fogEnabled=false;foreach(var u in w.units){if(u.Point!=null)u.BeginExit();u.Motor.Stop();u.transform.position=new Vector3(u.ownerId=="A"?-44:44,-27);}
   hud=UnityEngine.Object.FindObjectOfType<CampaignHUD>();var context=w.GetComponent<UnitContextOrders>();var infantry=w.units.First(u=>u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry);var other=w.units.First(u=>u!=infantry&&u.ownerId=="A"&&u.combatDefinition.role==UnitRole.Infantry);var city=w.points.First(p=>p.ownerId=="A");infantry.transform.position=city.transform.position;other.transform.position=city.transform.position+Vector3.up*2;hud.SelectUnit(infantry);
   Check(MouseModeStateMachine.MarchHotkey(KeyCode.Q)==MouseCommandMode.RoadMarch,"Q maps to road path setting");Check(MouseModeStateMachine.MarchHotkey(KeyCode.E)==MouseCommandMode.FreeMarch,"E maps to straight path setting");Check(MouseModeStateMachine.MarchHotkey(KeyCode.Alpha1)==MouseCommandMode.None&&MouseModeStateMachine.MarchHotkey(KeyCode.Alpha2)==MouseCommandMode.None,"numeric split keys no longer change march mode");
   foreach(var key in new[]{KeyCode.Alpha1,KeyCode.Keypad1,KeyCode.Alpha2,KeyCode.Keypad2,KeyCode.Alpha3,KeyCode.Keypad3}){DetachmentKind kind;Check(UnitContextOrders.SplitHotkey(key,out kind),key+" is a split key");Check(kind==(key==KeyCode.Alpha1||key==KeyCode.Keypad1?DetachmentKind.Flank:key==KeyCode.Alpha2||key==KeyCode.Keypad2?DetachmentKind.Feint:DetachmentKind.Infiltrate),key+" maps to correct split kind");}
   foreach(var key in new[]{KeyCode.Alpha4,KeyCode.Alpha5,KeyCode.Keypad4,KeyCode.Keypad5,KeyCode.Q,KeyCode.E,KeyCode.J,KeyCode.K}){DetachmentKind kind;Check(!UnitContextOrders.SplitHotkey(key,out kind),key+" cannot accidentally split");}
   foreach(var kind in new[]{DetachmentKind.Flank,DetachmentKind.Feint,DetachmentKind.Infiltrate}){
    hud.SelectUnit(infantry);infantry.SetPersonnelExact(infantry.Capacity);float people=infantry.Personnel;int count=w.units.Count(u=>u!=null&&u.Alive);Check(context.PreviewSplit(kind),kind+" preview opens");Check(context.SplitPreviewActive,kind+" pending confirmation");Check(w.units.Count(u=>u!=null&&u.Alive)==count,kind+" first press creates no unit");Near(infantry.Personnel,people,kind+" first press preserves source personnel");float expected=people*(kind==DetachmentKind.Flank?.5f:kind==DetachmentKind.Feint?2f/3:1f/3);Near(context.PreviewDetachedPeople,expected,kind+" preview uses actual split formula");Near(context.PreviewOriginalPeople+context.PreviewDetachedPeople,people,kind+" preview conserves personnel");Check(context.PreviewSplit(kind),kind+" second matching press confirms");Check(!context.SplitPreviewActive,kind+" confirmation closes preview");var child=w.units.First(u=>TacticalDetachment.Family(infantry,u));Near(child.Personnel,expected,kind+" actual split matches preview");Near(infantry.Personnel+child.Personnel,people,kind+" actual split conserves personnel");child.transform.position=infantry.transform.position;Check(TacticalDetachment.Merge(w,child,infantry).accepted,kind+" family merges after confirmed split");UnityEngine.Object.DestroyImmediate(infantry.GetComponent<TacticalDetachment>());
   }
   hud.SelectUnit(infantry);context.PreviewSplit(DetachmentKind.Flank);context.CancelSplitPreview();Check(!context.SplitPreviewActive&&infantry.GetComponent<TacticalDetachment>()==null,"cancel closes preview without splitting");
   context.PreviewSplit(DetachmentKind.Flank);context.PreviewSplit(DetachmentKind.Feint);Check(context.SplitPreviewActive&&infantry.GetComponent<TacticalDetachment>()==null,"different split key replaces preview instead of confirming");Near(context.PreviewDetachedPeople,infantry.Capacity*2/3,"replaced preview shows new ratio");context.CancelSplitPreview();
   infantry.SetPersonnelExact(infantry.Capacity*.4f);context.PreviewSplit(DetachmentKind.Feint);Near(context.PreviewDetachedPeople,infantry.Personnel/3,"damaged feint preview respects existing fallback rule");context.CancelSplitPreview();infantry.SetPersonnelExact(infantry.Capacity);
   context.PreviewSplit(DetachmentKind.Flank);infantry.Damage(1);context.PreviewSplit(DetachmentKind.Flank);Check(context.SplitPreviewActive&&infantry.GetComponent<TacticalDetachment>()==null,"changed personnel requires fresh preview before confirmation");context.CancelSplitPreview();
   context.PreviewSplit(DetachmentKind.Flank);hud.SelectUnit(other);context.PreviewSplit(DetachmentKind.Flank);Check(context.SplitPreviewActive&&other.GetComponent<TacticalDetachment>()==null,"selection change never confirms previous unit");context.CancelSplitPreview();hud.SelectUnit(infantry);
   context.PreviewSplit(DetachmentKind.Flank);w.setup.modes.SelectMarch(MouseCommandMode.RoadMarch);Check(!context.SplitPreviewActive&&!w.GetComponent<LocalPrototypeOrders>().Drafting&&w.setup.modes.CurrentMode==MouseCommandMode.RoadMarch,"Q switches to immediate A-star mode and cancels old split preview");w.GetComponent<LocalPrototypeOrders>().CancelDraft();Check(w.GetComponent<LocalTacticalBattle>().Move(infantry.transform.position+Vector3.right*.1f,null)==1,"A-star destination click issues movement immediately");w.setup.modes.SelectMarch(MouseCommandMode.RoadMarch);Check(infantry.Motor.IsMoving&&!w.GetComponent<LocalPrototypeOrders>().Drafting,"repeated Q never opens draft or interrupts existing route");infantry.Motor.Stop();w.setup.modes.SelectMarch(MouseCommandMode.FreeMarch);Check(!w.GetComponent<LocalPrototypeOrders>().Drafting&&w.setup.modes.CurrentMode==MouseCommandMode.FreeMarch,"E selects immediate straight mode");
   context.PreviewSplit(DetachmentKind.Flank);w.GetComponent<LocalCoordinatedOrders>().BeginPicking(LocalCoordinatedOrders.PickMode.Rotation);Check(!context.SplitPreviewActive,"rotation setup cancels old split preview");w.GetComponent<LocalCoordinatedOrders>().CancelPicking();
   var truck=w.units.First(u=>u.ownerId=="A"&&u.GetComponent<TransportTruck>()!=null).GetComponent<TransportTruck>();hud.SelectUnit(truck.Unit);truck.SetCargo(1);Check(!context.PreviewSplit(DetachmentKind.Flank),"loaded resource truck cannot preview an invalid split");truck.SetCargo(0);hud.SelectUnit(infantry);infantry.SetPersonnelExact(infantry.Capacity);
   var buttons=hud.GetComponentsInChildren<Button>(true);foreach(var name in new[]{"自动寻路 Q","直线行军 E","巡逻运输 R","轮换 K","联防 H"})Check(buttons.Any(b=>b.name==name),"UI displays "+name);
   context.PreviewSplit(DetachmentKind.Flank);Check(w.GetComponent<BattleCommandService>().Submit(new BattleCommand{kind=BattleCommandKind.StopMovement,playerId="A",unitId=infantry.unitId}).accepted,"stop command accepted during preview");Check(!context.SplitPreviewActive,"new unit command cancels pending split preview");
   Check(context.PreviewSplit(DetachmentKind.Infiltrate),"final preview ready for visual inspection");Check(context.SplitPreviewText.Contains("再次按 3")&&context.SplitPreviewText.Contains("Esc"),"preview shows matching confirmation key and cancel hint");
  }
  static void Capture(){var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();var camera=w.setup.mapCamera;var canvas=hud.GetComponentInParent<Canvas>();canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=camera;canvas.planeDistance=5;var rt=new RenderTexture(1280,900,24);camera.targetTexture=rt;Canvas.ForceUpdateCanvases();camera.Render();var old=RenderTexture.active;RenderTexture.active=rt;var texture=new Texture2D(1280,900,TextureFormat.RGB24,false);texture.ReadPixels(new Rect(0,0,1280,900),0,0);texture.Apply();File.WriteAllBytes(Path.Combine(Root,"split-preview.png"),texture.EncodeToPNG());RenderTexture.active=old;camera.targetTexture=null;UnityEngine.Object.DestroyImmediate(texture);UnityEngine.Object.DestroyImmediate(rt);}
  static void Poll(){try{if(EditorApplication.timeSinceStartup-started>180)throw new Exception("timeout");if(!EditorApplication.isPlaying||Time.time<1)return;var w=UnityEngine.Object.FindObjectOfType<BattleWorld>();if(w==null||!w.Initialized)return;if(phase==0){Test(w);phase=1;return;}if(phase++<5)return;Capture();Finish(null);}catch(Exception e){Finish(e);}}
  static void Finish(Exception e){if(e!=null){rows.Add("FAIL "+e);Debug.LogException(e);}File.WriteAllLines(Path.Combine(Root,"hotkey-verification.txt"),rows);SessionState.SetBool(Key,false);EditorApplication.update-=Poll;EditorApplication.Exit(e==null?0:1);}
 }
}
